13	/// A progress spinner for long-running operations.
14	pub struct ProgressSpinner {
15	    bar: ProgressBar,
16	    indent: usize,
17	}
18	
19	impl ProgressSpinner {
20	    /// Create a new spinner with a message.
21	    pub fn new(message: &str) -> Self {
22	        Self::with_indent(message, 0)
23	    }
24	
25	    /// Create a new spinner with indentation.
26	    pub fn with_indent(message: &str, indent: usize) -> Self {
27	        Self::create(message, indent, None)
28	    }
29	
30	    /// Create a new spinner inside a [`MultiProgress`].
31	    ///
32	    /// The spinner bar is inserted *before* the last bar (the pinned
33	    /// workflow progress bar), so it renders above it.
34	    pub fn with_multi(message: &str, indent: usize, multi: &MultiProgress) -> Self {
35	        Self::create(message, indent, Some(multi))
36	    }
37	
38	    fn create(message: &str, indent: usize, multi: Option<&MultiProgress>) -> Self {
39	        let raw_bar = ProgressBar::new_spinner();
40	        let prefix = " ".repeat(indent);
41	        raw_bar.set_style(
42	            ProgressStyle::default_spinner()
43	                .tick_chars("⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏")
44	                .template(&format!("{}{{spinner:.magenta}} {{msg}}", prefix))
45	                .unwrap(),
46	        );
47	        raw_bar.set_message(message.to_string());
48	        raw_bar.enable_steady_tick(Duration::from_millis(80));
49	
50	        // If a multi-progress is provided, insert the spinner above the
51	        // last bar (the pinned workflow progress bar). `insert_from_back(1)`
52	        // puts it just before the final bar.
53	        let bar = if let Some(multi) = multi {
54	            multi.insert_from_back(1, raw_bar)
55	        } else {
56	            raw_bar
57	        };
58	
59	        Self { bar, indent }
60	    }
61	
62	    /// Create a spinner that doesn't show (for silent mode).
63	    pub fn hidden() -> Self {
64	        let bar = ProgressBar::hidden();
65	        Self { bar, indent: 0 }
66	    }
67	
68	    /// Get a clone of the inner progress bar for use in callbacks.
69	    ///
70	    /// This is useful for live output streaming: the cloned bar can be
71	    /// passed to a callback running on another thread, and `set_message`
72	    /// calls on it will update the spinner display in real-time.
73	    pub fn bar_clone(&self) -> ProgressBar {
74	        self.bar.clone()
75	    }
76	}
77	
78	impl SpinnerHandle for ProgressSpinner {
79	    fn set_message(&mut self, msg: &str) {
80	        self.bar.set_message(msg.to_string());
81	    }
82	
83	    fn finish_success(&mut self, msg: &str) {
84	        let prefix = " ".repeat(self.indent);
85	        let theme = BivvyTheme::new();
86	        self.bar
87	            .set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
88	        self.bar
89	            .finish_with_message(format!("{}{}", prefix, theme.format_success(msg)));
90	    }
91	
92	    fn finish_error(&mut self, msg: &str) {
93	        let prefix = " ".repeat(self.indent);
94	        let theme = BivvyTheme::new();
95	        self.bar
96	            .set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
97	        self.bar
98	            .finish_with_message(format!("{}{}", prefix, theme.format_error(msg)));
99	    }
100	
101	    fn finish_skipped(&mut self, msg: &str) {
102	        let prefix = " ".repeat(self.indent);
103	        let theme = BivvyTheme::new();
104	        self.bar
105	            .set_style(ProgressStyle::default_spinner().template("{msg}").unwrap());
106	        self.bar
107	            .finish_with_message(format!("{}{}", prefix, theme.format_skipped(msg)));
108	    }
109	
110	    fn finish_and_clear(&mut self) {
111	        self.bar.finish_and_clear();
112	    }
113	
114	    fn progress_bar(&self) -> Option<ProgressBar> {
115	        Some(self.bar.clone())
116	    }
117	}
118	
119	/// Create a step-style spinner.
120	pub fn step_spinner(step_name: &str, description: &str) -> ProgressSpinner {
121	    let msg = format!("{} - {}", step_name, description);
122	    ProgressSpinner::new(&msg)
123	}
124	
125	/// Create an output callback that updates a spinner with live output lines.
126	///
127	/// The callback maintains a ring buffer of the last `max_lines` output lines
128	/// and updates the spinner message to show the base message plus those lines.
129	/// This gives users feedback that a command is actually making progress.
130	///
131	/// # Arguments
132	/// * `bar` - A cloned `ProgressBar` from the spinner
133	/// * `base_message` - The primary spinner message (e.g., "Running install_deps...")
134	/// * `indent` - Number of spaces to indent live output lines
135	/// * `max_lines` - Maximum number of live output lines to show (2-3 typical)
136	pub fn live_output_callback(
137	    bar: ProgressBar,
138	    base_message: String,
139	    indent: usize,
140	    max_lines: usize,
141	) -> crate::shell::OutputCallback {
142	    let buffer: Arc<Mutex<VecDeque<String>>> = Arc::new(Mutex::new(VecDeque::new()));
143	    let theme = BivvyTheme::new();
144	
145	    Box::new(move |line: OutputLine| {
146	        let text = match &line {
147	            OutputLine::Stdout(s) => s.trim_end().to_string(),
148	            OutputLine::Stderr(s) => s.trim_end().to_string(),
149	        };
150	
151	        // Skip empty lines
152	        if text.is_empty() {
153	            return;
154	        }
155	
156	        // Truncate long lines for display
157	        let display_text = if text.len() > 72 {
158	            format!("{}...", &text[..69])
159	        } else {
160	            text
161	        };
162	
163	        let mut buf = buffer.lock().unwrap();
164	        buf.push_back(display_text);
165	        while buf.len() > max_lines {
166	            buf.pop_front();
167	        }
168	
169	        // Build multi-line message: base message + indented output lines
170	        let prefix = " ".repeat(indent);
171	        let mut msg = base_message.clone();
172	        for line in buf.iter() {
173	            msg.push('\n');
174	            msg.push_str(&prefix);
175	            msg.push_str(&theme.dim.apply_to(format!("» {}", line)).to_string());
176	        }
177	
178	        bar.set_message(msg);
179	    })
180	}
