525	    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
526	        // Non-interactive: reuse env override or default logic.
527	        let is_multiselect = matches!(
528	            prompt.prompt_type,
529	            crate::ui::PromptType::MultiSelect { .. }
530	        );
531	        if let Some(result) = crate::ui::prompts::env_override(prompt) {
532	            return Ok(result);
533	        }
534	        if let Some(default) = &prompt.default {
535	            if is_multiselect {
536	                let values: Vec<String> =
537	                    default.split(',').map(|s| s.trim().to_string()).collect();
538	                return Ok(PromptResult::Strings(values));
539	            }
540	            return Ok(PromptResult::String(default.clone()));
541	        }
542	        Err(crate::error::BivvyError::ConfigValidationError {
543	            message: format!(
544	                "Cannot prompt for '{}' in non-interactive mode (no default value)",
545	                prompt.key
546	            ),
547	        })
548	    }
