156	
157	            let action = step_mgr.execute(
158	                &exec_opts,
159	                &mut context,
160	                step_overrides,
161	                &mut gap_checker,
162	                &mut self.snapshot_store,
163	                &self.steps,
164	                state.as_deref(),
