        let region = surface.create_transient_spinner("Running...", 4, 3);
        assert_eq!(region.max_lines(), 3);
    }

    #[test]
    fn create_transient_spinner_sets_message() {
        let surface = TerminalSurface::hidden();
        let region = surface.create_transient_spinner("Building project", 0, 1);
        let bar = region.bar_clone().expect("spinner should have a bar");
        assert_eq!(bar.message(), "Building project");
    }

    #[test]
    fn create_transient_spinner_clears_on_drop() {
        let surface = TerminalSurface::hidden();
        {
            let _region = surface.create_transient_spinner("Compiling...", 2, 2);
        }
        // Region dropped — finish_and_clear was called. No panic = pass.
    }

    #[test]
    fn create_pinned_message_bar_returns_handle() {
        let surface = TerminalSurface::hidden();
        let pinned = surface.create_pinned_message_bar("0/5 steps");
        assert!(pinned.bar_clone().is_some());
    }

    #[test]
    fn create_pinned_message_bar_sets_initial_message() {
        let surface = TerminalSurface::hidden();
        let pinned = surface.create_pinned_message_bar("progress info");
        let bar = pinned.bar_clone().expect("pinned should have a bar");
        assert_eq!(bar.message(), "progress info");
    }

    #[test]
    fn create_pinned_message_bar_message_updates() {
        let surface = TerminalSurface::hidden();
        let pinned = surface.create_pinned_message_bar("initial");
        pinned.set_message("updated");
        let bar = pinned.bar_clone().expect("pinned should have a bar");
        assert_eq!(bar.message(), "updated");
    }
}

