/// Create a spinner-style transient region above the pinned bar.
///
/// Centralizes spinner construction so callers don't need to depend
/// on `indicatif` directly. The spinner uses the standard Bivvy tick
/// characters and magenta color.
pub fn create_transient_spinner(
    self: &Arc<Self>,
    message: &str,
    indent: usize,
    max_lines: usize,
) -> TransientRegion {
    let bar = ProgressBar::new_spinner();
    let prefix = " ".repeat(indent);
    bar.set_style(
        ProgressStyle::default_spinner()
            .tick_chars("⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏")
            .template(&format!("{}{{spinner:.magenta}} {{msg}}", prefix))
            .unwrap(),
