//! Cache storage implementation.

use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs;
use std::path::{Path, PathBuf};

use super::entry::CacheEntry;

/// Storage for cached templates.
pub struct CacheStore {
    /// Root directory for cache.
    root: PathBuf,
}

impl CacheStore {
    /// Create a new cache store.
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

    /// Get the cache root directory.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Ensure the cache directory exists.
    fn ensure_dir(&self) -> Result<()> {
        fs::create_dir_all(&self.root)
            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
    }

    /// Get the path for storing an entry's content.
    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        let key = format!("{}:{}", source_id, template_name);
        let hash = Sha256::digest(key.as_bytes());
        let hash_str = hex::encode(&hash[..16]);
        self.root.join(hash_str)
    }

    /// Get the metadata file path for an entry.
    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        self.content_path(source_id, template_name)
            .with_extension("meta.json")
    }

    /// Store content and return a cache entry.
    pub fn store(
        &self,
        source_id: &str,
        template_name: &str,
        content: &str,
        ttl_seconds: u64,
    ) -> Result<CacheEntry> {
        self.ensure_dir()?;

        let content_path = self.content_path(source_id, template_name);
        fs::write(&content_path, content)?;

        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
            .with_size(content.len() as u64);

        self.save_metadata(&entry)?;

        Ok(entry)
    }

    /// Load a cached entry's metadata.
    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
        let meta_path = self.metadata_path(source_id, template_name);

        if !meta_path.exists() {
            return Ok(None);
        }

        let json = fs::read_to_string(&meta_path)?;
        let entry: CacheEntry = serde_json::from_str(&json)?;

        Ok(Some(entry))
    }

    /// Read the cached content.
    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
        fs::read_to_string(&entry.content_path).with_context(|| {
            format!(
                "Failed to read cached content from {:?}",
                entry.content_path
            )
        })
    }

    /// Save entry metadata.
    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
        let json = serde_json::to_string_pretty(entry)?;
        fs::write(&meta_path, json)?;
        Ok(())
    }

    /// Update an entry's metadata (e.g., after revalidation).
    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
        self.save_metadata(entry)
    }

    /// Remove a cached entry.
    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
        let content_path = self.content_path(source_id, template_name);
        let meta_path = self.metadata_path(source_id, template_name);

        let mut removed = false;

        if content_path.exists() {
            fs::remove_file(&content_path)?;
            removed = true;
        }

        if meta_path.exists() {
            fs::remove_file(&meta_path)?;
            removed = true;
        }

        Ok(removed)
    }

    /// List all cached entries.
    pub fn list(&self) -> Result<Vec<CacheEntry>> {
        self.ensure_dir()?;

        let mut entries = Vec::new();

        for entry in fs::read_dir(&self.root)? {
            let entry = entry?;
            let path = entry.path();

            if path.extension().is_some_and(|e| e == "json") {
                if let Ok(json) = fs::read_to_string(&path) {
                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
                        entries.push(cache_entry);
                    }
                }
            }
        }

        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
        Ok(entries)
    }

    /// Clear all cached entries.
    pub fn clear(&self) -> Result<usize> {
        let entries = self.list()?;
        let count = entries.len();

        for entry in entries {
            let _ = self.remove(&entry.source_id, &entry.template_name);
        }

        Ok(count)
    }

    /// Get total cache size in bytes.
    pub fn total_size(&self) -> Result<u64> {
        let entries = self.list()?;
        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn cache_store_creation() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        assert_eq!(store.root(), temp.path());
    }

    #[test]
    fn store_and_load() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "template content", 3600)
            .unwrap();

        assert_eq!(entry.source_id, "http:test");
        assert_eq!(entry.template_name, "template1");

        let loaded = store.load("http:test", "template1").unwrap().unwrap();
        assert_eq!(loaded.source_id, entry.source_id);
        assert_eq!(loaded.template_name, entry.template_name);
    }

    #[test]
    fn read_content() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "hello world", 3600)
            .unwrap();

        let content = store.read_content(&entry).unwrap();
        assert_eq!(content, "hello world");
    }

    #[test]
    fn load_nonexistent_returns_none() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let result = store.load("http:test", "nonexistent").unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn remove_entry() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        let removed = store.remove("http:test", "template1").unwrap();
        assert!(removed);

        let loaded = store.load("http:test", "template1").unwrap();
        assert!(loaded.is_none());
    }

    #[test]
    fn remove_nonexistent_returns_false() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let removed = store.remove("http:test", "nonexistent").unwrap();
        assert!(!removed);
    }

    #[test]
    fn list_entries() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content1", 3600)
            .unwrap();
        store
            .store("http:test", "template2", "content2", 3600)
            .unwrap();

        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 2);
    }

    #[test]
    fn clear_cache() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content1", 3600)
            .unwrap();
        store
            .store("http:test", "template2", "content2", 3600)
            .unwrap();

        let cleared = store.clear().unwrap();
        assert_eq!(cleared, 2);

        let entries = store.list().unwrap();
        assert!(entries.is_empty());
    }

    #[test]
    fn total_size_calculation() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store.store("http:test", "t1", "12345", 3600).unwrap(); // 5 bytes
        store.store("http:test", "t2", "1234567890", 3600).unwrap(); // 10 bytes

        let total = store.total_size().unwrap();
        assert_eq!(total, 15);
    }

    #[test]
    fn content_path_is_deterministic() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template");
        let path2 = store.content_path("http:test", "template");

        assert_eq!(path1, path2);
    }

    #[test]
    fn different_entries_have_different_paths() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template1");
        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }
}

//! Session storage.

use std::fs;
use std::path::PathBuf;

use anyhow::{Context, Result};

use super::{SessionId, SessionMetadata};

/// A complete session record.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct Session {
    /// Unique session identifier.
    pub id: SessionId,
    /// Session metadata.
    pub metadata: SessionMetadata,
}

/// Storage for sessions.
pub struct SessionStore {
    path: PathBuf,
}

impl SessionStore {
    /// Create a new session store.
    pub fn new(path: impl Into<PathBuf>) -> Self {
        Self { path: path.into() }
    }

    /// Ensure the store directory exists.
    fn ensure_dir(&self) -> Result<()> {
        fs::create_dir_all(&self.path)
            .with_context(|| format!("Failed to create session store at {:?}", self.path))
    }

    /// Get the path for a session file.
    fn session_path(&self, id: &SessionId) -> PathBuf {
        self.path.join(format!("{}.json", id))
    }

    /// Save a session.
    pub fn save(&self, session: &Session) -> Result<()> {
        self.ensure_dir()?;
        let path = self.session_path(&session.id);
        let json = serde_json::to_string_pretty(session)?;
        fs::write(&path, json).with_context(|| format!("Failed to write session to {:?}", path))
    }

    /// Load a session by ID.
    pub fn load(&self, id: &SessionId) -> Result<Session> {
        let path = self.session_path(id);
        let json =
            fs::read_to_string(&path).with_context(|| format!("Session not found: {:?}", path))?;
        serde_json::from_str(&json).context("Failed to parse session")
    }

    /// Get the most recent session.
    pub fn get_latest(&self) -> Result<Option<Session>> {
        let sessions = self.list_recent(1)?;
        Ok(sessions.into_iter().next())
    }

    /// List recent sessions.
    pub fn list_recent(&self, limit: usize) -> Result<Vec<Session>> {
        self.ensure_dir()?;

        let mut sessions = Vec::new();
        for entry in fs::read_dir(&self.path)? {
            let entry = entry?;
            let path = entry.path();
            if path.extension().is_some_and(|e| e == "json") {
                if let Ok(json) = fs::read_to_string(&path) {
                    if let Ok(session) = serde_json::from_str::<Session>(&json) {
                        sessions.push(session);
                    }
                }
            }
        }

        // Sort by timestamp descending
        sessions.sort_by(|a, b| b.id.timestamp().cmp(&a.id.timestamp()));
        sessions.truncate(limit);

        Ok(sessions)
    }

    /// Clean up old sessions (keep last N).
    pub fn cleanup(&self, keep: usize) -> Result<usize> {
        let sessions = self.list_recent(usize::MAX)?;
        let mut removed = 0;

        for session in sessions.into_iter().skip(keep) {
            let path = self.session_path(&session.id);
            if fs::remove_file(&path).is_ok() {
                removed += 1;
            }
        }

        Ok(removed)
    }

    /// Get the store path.
    pub fn path(&self) -> &PathBuf {
        &self.path
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn session_store_save_and_load() {
        let temp = TempDir::new().unwrap();
        let store = SessionStore::new(temp.path().join("sessions"));

        let id = SessionId::new();
        let mut meta = SessionMetadata::new("list", vec![]);
        meta.finalize(0, "output".to_string(), String::new());

        let session = Session {
            id: id.clone(),
            metadata: meta,
        };
        store.save(&session).unwrap();

        let loaded = store.load(&id).unwrap();
        assert_eq!(loaded.metadata.command, "list");
    }

    #[test]
    fn session_store_list_recent() {
        let temp = TempDir::new().unwrap();
        let store = SessionStore::new(temp.path().join("sessions"));

        // Create 3 sessions
        for cmd in ["list", "status", "run"] {
            let id = SessionId::new();
            let mut meta = SessionMetadata::new(cmd, vec![]);
            meta.finalize(0, String::new(), String::new());
            store.save(&Session { id, metadata: meta }).unwrap();
            // Small delay to ensure different timestamps
            std::thread::sleep(std::time::Duration::from_millis(5));
        }

        let recent = store.list_recent(10).unwrap();
        assert_eq!(recent.len(), 3);
        // Should be sorted by timestamp descending
        assert_eq!(recent[0].metadata.command, "run");
    }

    #[test]
    fn session_store_get_latest() {
        let temp = TempDir::new().unwrap();
        let store = SessionStore::new(temp.path().join("sessions"));

        let id1 = SessionId::new();
        let mut meta1 = SessionMetadata::new("list", vec![]);
        meta1.finalize(0, String::new(), String::new());
        store
            .save(&Session {
                id: id1,
                metadata: meta1,
            })
            .unwrap();

        std::thread::sleep(std::time::Duration::from_millis(10));

        let id2 = SessionId::new();
        let mut meta2 = SessionMetadata::new("run", vec![]);
        meta2.finalize(0, String::new(), String::new());
        store
            .save(&Session {
                id: id2.clone(),
                metadata: meta2,
            })
            .unwrap();

        let latest = store.get_latest().unwrap().unwrap();
        assert_eq!(latest.id, id2);
    }

    #[test]
    fn session_store_cleanup() {
        let temp = TempDir::new().unwrap();
        let store = SessionStore::new(temp.path().join("sessions"));

        // Create 5 sessions
        for i in 0..5 {
            let id = SessionId::new();
            let mut meta = SessionMetadata::new(format!("cmd{}", i), vec![]);
            meta.finalize(0, String::new(), String::new());
            store.save(&Session { id, metadata: meta }).unwrap();
            std::thread::sleep(std::time::Duration::from_millis(5));
        }

        // Keep only last 2
        let removed = store.cleanup(2).unwrap();
        assert_eq!(removed, 3);

        let remaining = store.list_recent(10).unwrap();
        assert_eq!(remaining.len(), 2);
    }

    #[test]
    fn session_store_empty_list() {
        let temp = TempDir::new().unwrap();
        let store = SessionStore::new(temp.path().join("sessions"));

        let recent = store.list_recent(10).unwrap();
        assert!(recent.is_empty());
    }

    #[test]
    fn session_store_get_latest_empty() {
        let temp = TempDir::new().unwrap();
        let store = SessionStore::new(temp.path().join("sessions"));

        let latest = store.get_latest().unwrap();
        assert!(latest.is_none());
    }

    #[test]
    fn session_store_load_nonexistent() {
        let temp = TempDir::new().unwrap();
        let store = SessionStore::new(temp.path().join("sessions"));

        let id = SessionId::new();
        let result = store.load(&id);
        assert!(result.is_err());
    }
}

//! Automatic fix application.
//!
//! This module provides functionality for automatically fixing
//! configuration issues detected by lint rules.

use crate::lint::LintDiagnostic;
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

/// A code fix that can be applied automatically.
#[derive(Debug, Clone)]
pub struct Fix {
    /// File to modify.
    pub file: PathBuf,
    /// Start byte offset.
    pub start: usize,
    /// End byte offset.
    pub end: usize,
    /// Replacement text.
    pub replacement: String,
}

/// Result of attempting to apply fixes.
#[derive(Debug)]
pub struct FixResult {
    /// Number of fixes applied.
    pub applied: usize,
    /// Diagnostics that couldn't be auto-fixed.
    pub unfixable: Vec<LintDiagnostic>,
    /// Errors that occurred during fixing.
    pub errors: Vec<String>,
}

/// Engine for applying automatic fixes.
pub struct FixEngine;

impl FixEngine {
    /// Create a new fix engine.
    pub fn new() -> Self {
        Self
    }

    /// Apply fixes from diagnostics that support auto-fix.
    pub fn apply_fixes(&self, diagnostics: &[LintDiagnostic], fixes: &[Fix]) -> FixResult {
        let mut applied = 0;
        let mut errors = Vec::new();

        // Group fixes by file
        let mut fixes_by_file: HashMap<&Path, Vec<&Fix>> = HashMap::new();
        for fix in fixes {
            fixes_by_file
                .entry(fix.file.as_path())
                .or_default()
                .push(fix);
        }

        // Apply fixes to each file
        for (file, file_fixes) in fixes_by_file {
            match self.apply_fixes_to_file(file, &file_fixes) {
                Ok(count) => applied += count,
                Err(e) => errors.push(format!("{}: {}", file.display(), e)),
            }
        }

        // Collect unfixable diagnostics
        let unfixable = diagnostics
            .iter()
            .filter(|d| d.suggestion.is_none())
            .cloned()
            .collect();

        FixResult {
            applied,
            unfixable,
            errors,
        }
    }

    /// Preview fixes without applying them.
    pub fn preview_fixes(&self, fixes: &[Fix]) -> Vec<String> {
        fixes
            .iter()
            .map(|f| {
                format!(
                    "{}:{}-{}: Replace with '{}'",
                    f.file.display(),
                    f.start,
                    f.end,
                    f.replacement
                )
            })
            .collect()
    }

    fn apply_fixes_to_file(&self, file: &Path, fixes: &[&Fix]) -> Result<usize, String> {
        let content =
            fs::read_to_string(file).map_err(|e| format!("Failed to read file: {}", e))?;

        // Sort fixes by start position (reverse order for safe replacement)
        let mut sorted_fixes = fixes.to_vec();
        sorted_fixes.sort_by(|a, b| b.start.cmp(&a.start));

        let mut new_content = content;
        for fix in &sorted_fixes {
            if fix.start <= new_content.len() && fix.end <= new_content.len() {
                new_content = format!(
                    "{}{}{}",
                    &new_content[..fix.start],
                    &fix.replacement,
                    &new_content[fix.end..]
                );
            }
        }

        fs::write(file, new_content).map_err(|e| format!("Failed to write file: {}", e))?;

        Ok(sorted_fixes.len())
    }
}

impl Default for FixEngine {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn applies_simple_fix() {
        let temp = TempDir::new().unwrap();
        let config_path = temp.path().join("config.yml");
        fs::write(&config_path, "app_name: \"My App\"\n").unwrap();

        let fix = Fix {
            file: config_path.clone(),
            start: 10,
            end: 18,
            replacement: "\"my-app\"".to_string(),
        };

        let engine = FixEngine::new();
        let result = engine.apply_fixes(&[], &[fix]);

        assert_eq!(result.applied, 1);

        let content = fs::read_to_string(&config_path).unwrap();
        assert!(content.contains("my-app"));
    }

    #[test]
    fn applies_multiple_fixes_to_same_file() {
        let temp = TempDir::new().unwrap();
        let config_path = temp.path().join("config.yml");
        fs::write(&config_path, "aaa bbb ccc").unwrap();

        let fixes = vec![
            Fix {
                file: config_path.clone(),
                start: 0,
                end: 3,
                replacement: "AAA".to_string(),
            },
            Fix {
                file: config_path.clone(),
                start: 8,
                end: 11,
                replacement: "CCC".to_string(),
            },
        ];

        let engine = FixEngine::new();
        let result = engine.apply_fixes(&[], &fixes);

        assert_eq!(result.applied, 2);

        let content = fs::read_to_string(&config_path).unwrap();
        assert_eq!(content, "AAA bbb CCC");
    }

    #[test]
    fn reports_unfixable_diagnostics() {
        use crate::lint::{RuleId, Severity};

        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("circular-dependency"),
            Severity::Error,
            "Cannot auto-fix circular dependencies",
        )];

        let engine = FixEngine::new();
        let result = engine.apply_fixes(&diagnostics, &[]);

        assert_eq!(result.applied, 0);
        assert_eq!(result.unfixable.len(), 1);
    }

    #[test]
    fn preview_fixes_returns_descriptions() {
        let fix = Fix {
            file: PathBuf::from("config.yml"),
            start: 10,
            end: 20,
            replacement: "new_value".to_string(),
        };

        let engine = FixEngine::new();
        let previews = engine.preview_fixes(&[fix]);

        assert_eq!(previews.len(), 1);
        assert!(previews[0].contains("config.yml:10-20"));
        assert!(previews[0].contains("new_value"));
    }

    #[test]
    fn handles_file_not_found() {
        let fix = Fix {
            file: PathBuf::from("/nonexistent/path/config.yml"),
            start: 0,
            end: 5,
            replacement: "test".to_string(),
        };

        let engine = FixEngine::new();
        let result = engine.apply_fixes(&[], &[fix]);

        assert_eq!(result.applied, 0);
        assert_eq!(result.errors.len(), 1);
    }
}

